package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.SheetNotFoundException;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Keeps each sheet's periods: each uniquely named on the sheet, none overlapping another. */
@Service
public class PeriodService {

    private final PeriodRepository periods;
    private final SheetRepository sheets;
    private final Rollup rollup;
    private final Audit audit;

    public PeriodService(PeriodRepository periods, SheetRepository sheets, Rollup rollup, Audit audit) {
        this.periods = periods;
        this.sheets = sheets;
        this.rollup = rollup;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public List<Period> list(String sheetId) {
        if (!sheets.existsById(sheetId)) {
            throw new SheetNotFoundException();
        }
        return periods.findBySheetIdOrderByFromDateAsc(sheetId);
    }

    @Transactional
    public Period add(String sheetId, String user, String name, LocalDate from, LocalDate to) {
        // Locking the sheet makes two users' periods go one after the other, so neither misses an overlap.
        sheets.findForUpdateById(sheetId).orElseThrow(SheetNotFoundException::new);
        String n = name.trim();
        if (from.isAfter(to)) {
            throw new PeriodRefusedException("The from-date must be on or before the to-date.");
        }
        List<Period> existing = periods.findBySheetIdOrderByFromDateAsc(sheetId);
        if (existing.stream().anyMatch(p -> p.getName().equalsIgnoreCase(n))) {
            throw new PeriodRefusedException("That period name is already in use.");
        }
        existing.stream().filter(p -> p.overlaps(from, to)).findFirst().ifPresent(p -> {
            throw new PeriodRefusedException("The period overlaps " + p.getName() + ".");
        });
        Period period;
        try {
            period = periods.saveAndFlush(new Period(sheetId, n, from, to));
        } catch (DataIntegrityViolationException e) {
            throw new PeriodRefusedException("That period name is already in use.");
        }
        audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user
                + " period=" + n + " from=" + from + " to=" + to);
        return period;
    }

    /** Close a period, fixing its due-total as it is now; refused when it is already closed. */
    @Transactional
    public Period close(String sheetId, String user, long periodId) {
        // Locking the sheet makes the close and any claim change on the sheet go one after the other.
        sheets.findForUpdateById(sheetId).orElseThrow(SheetNotFoundException::new);
        Period period = periods.findByIdAndSheetId(periodId, sheetId).orElseThrow(PeriodNotFoundException::new);
        if (period.isClosed()) {
            throw new PeriodRefusedException("The period is already closed.");
        }
        BigDecimal total = rollup.dueBetween(sheetId, period.getFromDate(), period.getToDate());
        period.close(total);
        periods.saveAndFlush(period);
        audit.recordOnCommit("PERIOD_CLOSED sheet=" + sheetId + " by=" + user
                + " period=" + period.getName() + " total=" + total.toPlainString());
        return period;
    }
}
-- A period on the sheet: a name, unique on the sheet without regard to case, and a from and to date,
-- both inclusive. No two of a sheet's periods overlap (the service refuses one that would).
CREATE TABLE period (
    id        BIGINT        GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sheet_id  VARCHAR(200)  NOT NULL REFERENCES sheet (id),
    name      VARCHAR(200)  NOT NULL,
    name_key  VARCHAR(200)  GENERATED ALWAYS AS (LOWER(name)),
    from_date DATE          NOT NULL,
    to_date   DATE          NOT NULL,
    CHECK (from_date <= to_date)
);
CREATE UNIQUE INDEX period_sheet_name ON period (sheet_id, name_key);
-- A period can be closed: its due-total is then fixed at the figure it had when closed, and no claim
-- dated inside it can be added, edited, opened, settled or voided.
ALTER TABLE period ADD COLUMN closed BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE period ADD COLUMN closed_total DECIMAL(15, 2);
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session, isDate } from './session';

export interface Period {
  id: number;
  /** Unique on the sheet. */
  name: string;
  /** The first and last day of the period (YYYY-MM-DD), both inclusive. */
  from: string;
  to: string;
  /** Closed: its due-total is fixed and its claims can no longer change. */
  closed: boolean;
  /** The due-total fixed when it was closed, two decimals; null while open. */
  closedTotal: string | null;
}

export interface PeriodFields {
  name: string;
  /** Blank takes the sheet's today. */
  from: string;
  to: string;
}

// The active sheet's periods, by from-date, re-read from the server each time the sheet is loaded.
// No two overlap, so a date falls in at most one of them.
@Injectable({ providedIn: 'root' })
export class Periods {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  readonly periods = signal<Period[]>([]);
  private loads = 0;

  /** The period whose dates contain a date (YYYY-MM-DD), or undefined when none does. */
  of(date: string): Period | undefined {
    return this.periods().find((p) => p.from <= date && date <= p.to);
  }

  /** Re-read the active sheet's periods from the server; an error message when that failed. */
  async load(): Promise<string | null> {
    const user = this.session.user();
    const sid = this.session.sheetId();
    const load = ++this.loads;
    this.periods.set([]);
    if (!user || !sid) return null;
    try {
      const periods = await firstValueFrom(this.http.get<Period[]>(this.url(sid), { headers: { 'X-User': user } }));
      if (load === this.loads) this.periods.set([...periods].sort(byFrom));
      return null;
    } catch (e) {
      return e instanceof HttpErrorResponse ? `Could not load periods (${e.status}).` : 'Could not load periods.';
    }
  }

  /** Add a period; an error message when refused. */
  async add(f: PeriodFields): Promise<string | null> {
    if (!this.session.user() || !this.session.sheetId()) return 'Load a sheet first.';
    const name = f.name.trim();
    const from = f.from.trim() || this.session.today() || '';
    const to = f.to.trim();
    if (!name) return 'Enter a name.';
    if (!isDate(from) || !isDate(to)) return 'Enter the from and to dates as YYYY-MM-DD.';
    if (from > to) return 'The from-date must be on or before the to-date.';
    if (this.periods().some((p) => p.name.toLowerCase() === name.toLowerCase())) return 'That period name is already in use.';
    const clash = this.periods().find((p) => p.from <= to && from <= p.to);
    if (clash) return `The period overlaps ${clash.name}.`;
    const sid = this.session.sheetId()!;
    try {
      const period = await firstValueFrom(
        this.http.post<Period>(this.url(sid), { name, from, to }, { headers: { 'X-User': this.session.user()! } }),
      );
      if (this.session.sheetId() === sid) this.periods.update((ps) => [...ps, period].sort(byFrom));
      return null;
    } catch (e) {
      if (e instanceof HttpErrorResponse && e.status === 409) {
        return 'The period overlaps another, or its name is already in use.';
      }
      if (e instanceof HttpErrorResponse && e.status === 400) return 'Enter a name, and the from and to dates as YYYY-MM-DD.';
      return e instanceof HttpErrorResponse ? `Could not add period (${e.status}).` : 'Could not add period.';
    }
  }

  /** Close a period, fixing its due-total; an error message when refused. */
  async close(id: number): Promise<string | null> {
    const sid = this.session.sheetId();
    const user = this.session.user();
    if (!user || !sid) return 'Load a sheet first.';
    try {
      const period = await firstValueFrom(
        this.http.post<Period>(`${this.url(sid)}/${id}/close`, null, { headers: { 'X-User': user } }),
      );
      if (this.session.sheetId() === sid) this.periods.update((ps) => ps.map((p) => (p.id === id ? period : p)));
      return null;
    } catch (e) {
      if (e instanceof HttpErrorResponse && e.status === 409) return 'The period is already closed.';
      return e instanceof HttpErrorResponse ? `Could not close period (${e.status}).` : 'Could not close period.';
    }
  }

  private url(sid: string): string {
    return `/api/sheets/${encodeURIComponent(sid)}/periods`;
  }
}

function byFrom(a: Period, b: Period): number {
  return a.from.localeCompare(b.from);
}
import { Component, computed, inject, signal } from '@angular/core';
import { Claims } from '../../core/claims';
import { People, gradeOn } from '../../core/people';
import { Period, Periods } from '../../core/periods';
import { Rates, hundredths, money } from '../../core/rates';

// The sheet's periods: one form adds a period, and the list shows each with its dates and its
// due-total, the due of the claims that count whose date falls in it (fixed once it is closed), and
// whether it is closed, with a button to close it.
@Component({
  selector: 'app-periods',
  template: `
    <section aria-label="Periods" data-testid="periods">
      <h2>Periods</h2>
      <form (submit)="submit($event)" data-testid="period-form">
        <label for="period-form-name">Name</label>
        <input
          id="period-form-name"
          data-testid="period-form-name"
          [value]="name()"
          (input)="name.set(value($event)); error.set(null)"
        />
        <label for="period-form-from">From (YYYY-MM-DD)</label>
        <input
          id="period-form-from"
          data-testid="period-form-from"
          placeholder="YYYY-MM-DD"
          [value]="from()"
          (input)="from.set(value($event)); error.set(null)"
        />
        <label for="period-form-to">To (YYYY-MM-DD)</label>
        <input
          id="period-form-to"
          data-testid="period-form-to"
          placeholder="YYYY-MM-DD"
          [value]="to()"
          (input)="to.set(value($event)); error.set(null)"
        />
        <button type="submit" data-testid="period-form-submit" [disabled]="saving()">Add period</button>
        @if (error(); as err) {
          <p role="alert" data-testid="period-form-error">{{ err }}</p>
        }
      </form>
      <table data-testid="period-list">
        <thead>
          <tr><th scope="col">Name</th><th scope="col">From</th><th scope="col">To</th><th scope="col">Due total</th><th scope="col">Closed</th><th scope="col">Actions</th></tr>
        </thead>
        <tbody>
          @for (p of periods.periods(); track p.id) {
            <tr [attr.data-testid]="'period-row-' + p.name">
              <th scope="row" data-testid="period-name">{{ p.name }}</th>
              <td data-testid="period-from">{{ p.from }}</td>
              <td data-testid="period-to">{{ p.to }}</td>
              <td data-testid="period-due-total">{{ p.closedTotal ?? dueTotals().get(p.id) ?? '0.00' }}</td>
              <td data-testid="period-closed">{{ p.closed ? 'yes' : 'no' }}</td>
              <td>
                <button type="button" data-testid="period-close" [disabled]="acting() === p.id" (click)="close(p)">
                  Close<span class="visually-hidden"> period {{ p.name }}</span>
                </button>
                @if (actionError()?.id === p.id) {
                  <p role="alert" data-testid="period-error">{{ actionError()?.message }}</p>
                }
              </td>
            </tr>
          }
        </tbody>
      </table>
    </section>
  `,
})
export class PeriodsPanel {
  protected readonly periods = inject(Periods);
  private readonly claims = inject(Claims);
  private readonly people = inject(People);
  private readonly rates = inject(Rates);
  protected readonly name = signal('');
  protected readonly from = signal('');
  protected readonly to = signal('');
  protected readonly error = signal<string | null>(null);
  protected readonly saving = signal(false);
  /** The period whose action is under way, and the last action's refusal, by period. */
  protected readonly acting = signal<number | null>(null);
  protected readonly actionError = signal<{ id: number; message: string } | null>(null);

